UPDATE PAYMENT_RECOVERY_TASK
SET RECOVERY_STATUS = 'MANUAL_REVIEW',
    NEXT_RETRY_AT = NULL,
    CLAIM_TOKEN = NULL,
    LEASE_EXPIRES_AT = NULL,
    UPDATED_AT = CURRENT_TIMESTAMP
WHERE ID = #{taskId}
    AND RECOVERY_STATUS = 'RUNNING'
    AND CLAIM_TOKEN = #{claimToken}
    AND LEASE_EXPIRES_AT > #{now}
